'use client';

import type { HTMLAttributes } from 'react';
import { useEffect, useRef, useState } from 'react';
import { cx } from '@/utils/cx';

export type AvatarSize = 'xs' | 'sm' | 'md' | 'lg';
export type AvatarColor = 'neutral' | 'blue' | 'lime' | 'pink';

export type AvatarProps = Omit<HTMLAttributes<HTMLSpanElement>, 'color'> & {
  size?: AvatarSize;
  color?: AvatarColor;
  initials?: string;
  src?: string;
  alt?: string;
};

export function Avatar({ size = 'md', color = 'neutral', initials, src, alt, className, ...props }: AvatarProps) {
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const showImage = Boolean(src && src !== failedSource);

  useEffect(() => {
    const image = imageRef.current;
    if (!image || !src) return;
    const fail = () => setFailedSource(src);
    if (image.complete && image.naturalWidth === 0) fail();
    image.addEventListener('error', fail);
    return () => image.removeEventListener('error', fail);
  }, [src, showImage]);

  return (
    <span role="img" aria-label={alt || initials || 'Avatar'} data-size={size} data-color={color} className={cx('ui-avatar', className)} {...props}>
      <span className="ui-avatar__initials" aria-hidden="true">{initials}</span>
      {showImage && <img ref={imageRef} src={src} alt="" aria-hidden="true" loading="lazy" decoding="async" onError={() => setFailedSource(src!)} />}
    </span>
  );
}

import type { CSSProperties, ReactNode } from 'react';
import { cx } from '@/utils/cx';

/** A shared CSS/SVG metallic treatment. Decorative motion respects reduced motion. */
export function MetalSurface({ children, size = 56, className }: { children: ReactNode; size?: number; className?: string }) {
  return <span className={cx('ui-metal-surface', className)} style={{'--metal-size':`${size}px`} as CSSProperties} aria-hidden><span className="ui-metal-surface__sweep"/><span className="ui-metal-surface__content">{children}</span></span>;
}

import type { ReactNode } from 'react';
import { Avatar } from '@/components/base/avatar/avatar';
import { BrandMark } from '@/components/foundations/brand-mark';
import { cx } from '@/utils/cx';

export type MessageProps = {
  role: 'user'|'assistant'|'system';
  children: ReactNode;
  name?: string;
  avatar?: ReactNode;
  timestamp?: string;
  dateTime?: string;
  actions?: ReactNode;
  footer?: ReactNode;
  isStreaming?: boolean;
  variant?: 'workspace'|'plain'|'bubble';
  showHeader?: boolean;
  className?: string;
};

export function Message({role,children,name=role==='user'?'You':role==='assistant'?'Assistant':'System',avatar,timestamp,dateTime,actions,footer,isStreaming=false,variant='workspace',showHeader=false,className}: MessageProps) {
  return <article className={cx('ui-message',className)} data-role={role} data-variant={variant} aria-label={`${name} message`} aria-busy={isStreaming || undefined}>
    {variant==='workspace' && role==='assistant' && <span className="ui-message__avatar">{avatar ?? <BrandMark size={24}/>}</span>}
    <div className="ui-message__body">{showHeader && <header className="ui-message__header">{variant!=='workspace' && (avatar ?? (role==='user'?<Avatar size="xs" initials="Y" alt="You"/>:null))}<span>{name}</span>{timestamp && <time dateTime={dateTime}>{timestamp}</time>}</header>}
    <div className="ui-message__content">{children}</div>{footer && <div className="ui-message__footer">{footer}</div>}{actions && !isStreaming && <div className="ui-message__actions">{actions}</div>}</div>
  </article>;
}

import { MetalSurface } from '@/components/base/metal-surface/metal-surface';

export function BrandMark({ size = 34, appearance = 'accent' }: { size?: number; appearance?: 'accent' | 'metal' }) {
  if (appearance === 'metal') return <MetalSurface size={size}><svg width={size*.7} height={size*.7} viewBox="0 0 36 36" fill="none" aria-hidden><path d="M10.5 25.5L17.3 10.5H19L25.5 25.5M13.2 20H22.7" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round"/><circle cx="27" cy="9" r="2" fill="currentColor"/></svg></MetalSurface>;
  return (
    <svg width={size} height={size} viewBox="0 0 36 36" fill="none" aria-hidden="true">
      <rect x="1" y="1" width="34" height="34" rx="10" fill="var(--accent-strong)" />
      <rect x="1.5" y="1.5" width="33" height="33" rx="9.5" stroke="white" strokeOpacity=".25" />
      <path d="M10.5 25.5L17.3 10.5H19L25.5 25.5" stroke="white" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M13.2 20H22.7" stroke="white" strokeWidth="2.4" strokeLinecap="round" />
      <circle cx="27" cy="9" r="2" fill="white" fillOpacity=".55" />
    </svg>
  );
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
